// A terminal around the scene it wraps: a prompt above it and a status line
// with the time, the Wi-Fi signal and the battery below it. The prompt opens
// the scene list and the status line the frame's settings.
const pad = (n) => String(n).padStart(2, '0')

function status(frame, now) {
  const parts = [`${pad(now.getHours())}:${pad(now.getMinutes())}`]
  if (typeof frame.wifiRssi === 'number') parts.push(`wifi ${frame.wifiRssi} dBm`)
  if (typeof frame.batteryPercent === 'number') parts.push(`battery ${frame.batteryPercent}%`)
  return parts.join('  |  ')
}

export function get(app) {
  const { hostName, inkColor } = app.state
  const now = new Date()
  // The status line changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  return (
    <div className={`flex flex-col w-full h-full p-[1.5vh] bg-[#0b0f0c] text-[${inkColor}] text-[3.2vh]`}>
      <div className="flex items-center h-[6vh] min-w-0" onClick={() => frameos.dispatch('sceneSwitcher')}>
        <span className="truncate">{`${hostName}:~$ show ${app.frame.sceneName || 'scene'}`}</span>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 p-[1vh] border border-[${inkColor}]`}>
        <yield />
      </div>
      <div className="flex items-center h-[6vh] min-w-0" onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
        <span className="truncate">{status(app.frame, now)}</span>
      </div>
    </div>
  )
}

